function getFallback(cn, sub, count) { const exact = FALLBACK[`${cn}|${sub}`]; if (exact?.length >= 3) return [...exact].sort(() => Math.random() - .5).slice(0, Math.min(count, exact.length)); const merged = Object.keys(FALLBACK).filter(k => k.endsWith(`|${sub}`)).flatMap(k => FALLBACK[k] || []); if (merged.length >= 3) return [...merged].sort(() => Math.random() - .5).slice(0, Math.min(count, merged.length)); return []; }


